// And groups predicates with the AND operator between them.
func And(predicates ...predicate.RelationshipProjectionJob) predicate.RelationshipProjectionJob {
	return predicate.RelationshipProjectionJob(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.RelationshipProjectionJob) predicate.RelationshipProjectionJob {
	return predicate.RelationshipProjectionJob(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.RelationshipProjectionJob) predicate.RelationshipProjectionJob {
	return predicate.RelationshipProjectionJob(sql.NotPredicates(p))
}
